def lesson(key, title, mentor, theory, example, task, hints, criteria, errors, transfer, expected=None):
    return dict(id=key, title=title, mentor=mentor, goal=title + ': объяснить принцип и применить его в модели',
                prerequisites=['Чтение условия; выполнение в терминале не требуется'],
                explanation=theory, examples=[example], task=task, hints=hints,
                criteria=criteria, mistakes=errors, repetition=transfer,
                environment='Текстовая симуляция Linux. Никаких команд на macOS.',
                expected=expected)

